cat > /tmp/bot-check-$$/check.mjs <<'EOF'
import assert from 'node:assert/strict';
import { promises as fs } from 'node:fs';
import path from 'node:path';
const bot = await import(process.env.BOT_PATH);
const { recordUnsubscribe: unsub, recordResubscribe: resub, mayEmail } = bot;
const M = (to) => ({ to, kind: 'marketing' });
const T = (to) => ({ to, kind: 'transactional' });
const d = (ms) => new Date(ms);
const now = new Date();

// 1. nothing recorded -> allowed
assert.deepEqual(await mayEmail(M('new@shop.test'), now), { allowed: true, reason: null });

// 2. unsubscribe -> marketing blocked, transactional allowed
await unsub('Ann@Shop.test', d(1000));
assert.deepEqual(await mayEmail(M('ann@shop.test'), now), { allowed: false, reason: 'unsubscribed' });
assert.deepEqual(await mayEmail(T('ann@shop.test'), now), { allowed: true, reason: null });

// 3. header variant with display name and mailto, trailing dot in domain
assert.equal((await mayEmail(M('"Ann" <ANN@shop.test.>'), now)).reason, 'unsubscribed');
assert.equal((await mayEmail(M('mailto:ann@SHOP.test'), now)).reason, 'unsubscribed');

// 4. resubscribe at a later time re-enables marketing
await resub('ann@shop.test', d(2000));
assert.equal((await mayEmail(M('ann@shop.test'), now)).allowed, true);

// 5. out of order: an older unsubscribe arrives after the resubscribe -> still allowed
await unsub('ann@shop.test', d(1500));
assert.equal((await mayEmail(M('ann@shop.test'), now)).allowed, true);

// 6. newer unsubscribe after resubscribe -> blocked again
await unsub('ann@shop.test', d(3000));
assert.equal((await mayEmail(M('ann@shop.test'), now)).reason, 'unsubscribed');

// 7. resubscribe that arrives before the unsubscribe it should override (late unsub, older at)
await resub('bob@shop.test', d(5000));
await unsub('bob@shop.test', d(4000));
assert.equal((await mayEmail(M('bob@shop.test'), now)).allowed, true, 'resub newer than unsub');

// 8. exact tie -> unsubscribe wins
await unsub('tie@shop.test', d(7000));
await resub('tie@shop.test', d(7000));
assert.equal((await mayEmail(M('tie@shop.test'), now)).reason, 'unsubscribed');

// 9. gmail dot / plus / googlemail aliases share one key
await unsub('<EMAIL>', d(100));
assert.equal((await mayEmail(M('<EMAIL>'), now)).reason, 'unsubscribed');
assert.equal((await mayEmail(M('<EMAIL>'), now)).reason, 'unsubscribed');

// 10. non-gmail dots are significant
assert.equal((await mayEmail(M('j.doe@shop.test'), now)).allowed, true);

// 11. fail-closed rules
assert.deepEqual(await mayEmail({ to: 'x@shop.test', kind: 'promo' }, now), { allowed: false, reason: 'unknown_kind' });
assert.deepEqual(await mayEmail({ to: 'not-an-address', kind: 'marketing' }, now), { allowed: false, reason: 'invalid_recipient' });
assert.deepEqual(await mayEmail({ to: 'a@b', kind: 'marketing' }, now), { allowed: false, reason: 'invalid_recipient' });
assert.deepEqual(await mayEmail({ to: '<EMAIL>/evil', kind: 'marketing' }, now), { allowed: false, reason: 'invalid_recipient' });
await assert.rejects(unsub('a@shop.test', '2020-01-01'), TypeError);
await assert.rejects(unsub('nope', d(1)), TypeError);

// 12. torn write: junk without trailing newline, then a valid record must still be read
const file = (await fs.readdir(path.join(process.env.STATE_DIR, 'optout-events'))).length;
const torn = 'torn@shop.test';
await unsub(torn, d(10));
const f = path.join(process.env.STATE_DIR, 'optout-events');
const target = (await fs.readdir(f)).find(async () => true);
// append partial line to the torn@ file directly
const { createHash } = await import('node:crypto');
const tf = path.join(f, createHash('sha256').update('torn@shop.test').digest('hex') + '.log');
await fs.appendFile(tf, '\n{"v":1,"type":"resubscr');
await resub(torn, d(20));
assert.equal((await mayEmail(M(torn), now)).allowed, true, 'valid record after torn write is read');

// 13. concurrency: 300 parallel writers across the same address
await Promise.all(Array.from({ length: 300 }, (_, i) => unsub('race@shop.test', d(i))));
assert.equal((await mayEmail(M('race@shop.test'), now)).reason, 'unsubscribed');
await Promise.all(Array.from({ length: 300 }, (_, i) => resub('race@shop.test', d(1000 + i))));
assert.equal((await mayEmail(M('race@shop.test'), now)).allowed, true);
console.log('ALL IN-PROCESS CHECKS PASSED');
EOF
